//! 🧪️ Typed diagnostic projection preserves actual original text/vector allocations and the canonical wire bridge bytes.
use super::*;
use semio_framework_value::ToValue;
fn ordered(value:&mut DslValue){match value{DslValue::Object(rows)=>{rows.sort_by(|left,right|left.0.as_bytes().cmp(right.0.as_bytes()));for(_,value)in rows{ordered(value)}},DslValue::Array(rows)=>rows.iter_mut().for_each(ordered),_=>{}}}
#[test]
fn original_diagnostics_wire_projection_matches_canonical_record_without_a_value_shadow(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut rows=Vec::new();for index in 0..4{let mut scope=FaultScope::default();if index%2==0{scope.app_id=Some("app α🙂".into());scope.module=Some("same original".into());scope.plugin_id=Some("plugin".into());}else{scope.body_key=Some("body".into());scope.instance_id=Some("71".into());}rows.push(Diagnostic{code:semio_framework_diagnostic::FaultCode::new("native.fixture"),severity:[Severity::Info,Severity::Warning,Severity::Error,Severity::Fatal][index],span:TextSpan{line:u32::MAX,column:71,length:8197},message:"α🙂".repeat(8197),expected:(index%2==0).then(||ExpectedSet{tokens:vec!["(".into(),")".into()],keys:vec!["keys".into()],keywords:vec!["same original".into()]}),scope});assert_eq!(rows.last().unwrap().severity.to_value(),DslValue::String(law["severities"][index].as_str().unwrap().into()));}let pointers:Vec<_>=rows.iter().map(|row|(row.message.as_ptr(),row.code.0.as_ptr(),row.expected.as_ref().map(|expected|expected.tokens.as_ptr()))).collect();let mut reference=rows.to_value();ordered(&mut reference);let expected=super::super::super::encode_wire_value(&reference);for width in [1,7,64]{for cut in [Some(0),Some(1),Some(11),Some(71),Some(1001),None]{let source=BorrowedDiagnosticsWireValue::new(&rows);let mut cursor=pack::record::BorrowedProjectedPackCursor::default();let mut output=vec![0;width];let mut actual=Vec::new();for index in 0..2000000{if cut==Some(index){break}let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:cursor.next_minimum_copy_bytes().max(width),maximum_capacity_bytes:cursor.next_capacity_byte_demand().unwrap(),maximum_release_bytes:0,maximum_depth:cursor.next_advance_depth_demand().unwrap()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&source,BorrowedDiagnosticsWireValue::RECORD,&mut output,g).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));actual.extend_from_slice(&output[..step.written_bytes]);if step.complete{break}assert!(index<1999999);}if cut.is_none(){assert!(cursor.is_complete());assert_eq!(actual,expected);}while !cursor.terminal_is_empty(){let d=cursor.retirement_demands().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close(g).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));}assert_eq!(rows.iter().map(|row|(row.message.as_ptr(),row.code.0.as_ptr(),row.expected.as_ref().map(|expected|expected.tokens.as_ptr()))).collect::<Vec<_>>(),pointers);}}}
